-- Vibecoin · migration 013 · texto próprio das páginas de cotação (/cotacoes/<moeda>).
-- As 20 páginas tinham o mesmo modelo e só uma frase própria; o Google tende a deixar páginas assim fora do índice.
-- Cada moeda ganha: para que serve, como funciona a oferta, fatos e riscos (coluna JSON "about"). Conferido em 2026-11-25.

SET NAMES utf8mb4;

ALTER TABLE coins ADD COLUMN about JSON NULL AFTER description;

UPDATE coins SET about = '{"uso":"O bitcoin é usado principalmente como reserva de valor, uma espécie de \\"ouro digital\\" que muita gente compra para guardar por anos, e também para enviar dinheiro a qualquer lugar do mundo sem depender de banco. Empresas listadas em bolsa, fundos e até alguns governos mantêm bitcoin em caixa, e nos Estados Unidos e no Brasil existem fundos negociados em bolsa (ETFs) que acompanham o preço dele.","oferta":"Nunca vão existir mais de 21 milhões de bitcoins. Os novos são criados como recompensa para os mineradores, e essa recompensa cai pela metade a cada 210 mil blocos, mais ou menos a cada quatro anos, no evento chamado halving. O último foi em abril de 2024, quando a recompensa passou para 3,125 bitcoins por bloco. Mais de 19 milhões já foram emitidos.","fatos":[["Lançamento","Janeiro de 2009"],["Criador","Satoshi Nakamoto (pseudônimo)"],["Como a rede se mantém","Mineração (prova de trabalho)"],["Oferta máxima","21 milhões de BTC"],["Tempo médio de bloco","10 minutos"],["Menor fração","1 satoshi = 0,00000001 BTC"]],"riscos":"O preço do bitcoin já caiu mais de 70% em alguns ciclos e pode oscilar dezenas de pontos percentuais em poucas semanas. Quem guarda em carteira própria e perde a frase de recuperação perde o acesso para sempre, e transferências enviadas por engano não podem ser desfeitas.","guia":{"href":"/guias/o-que-e-bitcoin-de-verdade","titulo":"O que é bitcoin, de verdade"}}' WHERE slug = 'bitcoin';
UPDATE coins SET about = '{"uso":"O ethereum é uma plataforma onde rodam contratos inteligentes: programas que executam sozinhos o que foi combinado. Em cima dele funcionam stablecoins, aplicativos de finanças descentralizadas (DeFi), NFTs e projetos de tokenização de ativos como títulos e fundos. O ether (ETH) é a moeda usada para pagar as taxas da rede, chamadas de gas.","oferta":"O ether não tem limite fixo de oferta. Desde 2022 a rede funciona por prova de participação: validadores travam ether como garantia e recebem ether novo como recompensa. Ao mesmo tempo, parte de cada taxa paga é destruída (\\"queimada\\"), o que reduz a emissão líquida e, em períodos de muito uso, pode até diminuir a quantidade total.","fatos":[["Lançamento","Julho de 2015"],["Criadores","Vitalik Buterin e outros cofundadores"],["Como a rede se mantém","Validadores (prova de participação, desde setembro de 2022)"],["Oferta máxima","Sem limite fixo; parte das taxas é queimada"],["Taxas","Pagas em ETH (gas)"],["Redes de camada 2","Arbitrum, Optimism, Base e outras"]],"riscos":"Além da oscilação forte de preço, quem usa aplicativos sobre o ethereum corre o risco de falhas de programação nos contratos e de golpes com sites falsos que pedem permissão para movimentar a carteira. As taxas sobem bastante em momentos de rede cheia.","guia":{"href":"/guias/o-que-e-ethereum-e-para-que-serve","titulo":"O que é ethereum e para que serve"}}' WHERE slug = 'ethereum';
UPDATE coins SET about = '{"uso":"O tether (USDT) é uma stablecoin: uma moeda digital que busca valer sempre US$ 1. É a criptomoeda mais negociada do mundo, usada para sair e entrar de posições sem passar pelo real, para enviar dólares digitais entre países e como meio de pagamento em lugares com moeda local fraca. No Brasil, é a forma mais comum de ter \\"dólar em cripto\\".","oferta":"Não há limite de oferta: a Tether, empresa que emite a moeda, cria USDT quando recebe dólares e destrói quando devolve. Segundo a empresa, cada unidade é lastreada por reservas, a maior parte em títulos de curto prazo do governo americano. O USDT circula em várias redes, sendo TRON e ethereum as mais usadas.","fatos":[["Lançamento","2014"],["Emissor","Tether (empresa ligada à corretora Bitfinex)"],["Atrelada a","Dólar americano (US$ 1)"],["Oferta máxima","Sem limite; acompanha as reservas"],["Redes principais","TRON e ethereum, entre outras"],["Pode bloquear endereços?","Sim, o emissor pode congelar USDT"]],"riscos":"O valor depende da confiança nas reservas do emissor, que é uma empresa privada e já foi multada por autoridades americanas por informações sobre o lastro. O emissor pode congelar saldos. Para quem pensa em reais, o valor em reais sobe e desce com o dólar.","guia":{"href":"/guias/stablecoins-o-que-sao-e-para-que-servem","titulo":"Stablecoins: o que são e para que servem"}}' WHERE slug = 'tether';
UPDATE coins SET about = '{"uso":"O XRP é a moeda do XRP Ledger, uma rede criada para pagamentos e transferências internacionais rápidas e baratas. A empresa Ripple, principal apoiadora da rede, oferece a bancos e empresas de remessa serviços que podem usar o XRP como ponte entre moedas. Uma transferência na rede costuma ser confirmada em poucos segundos.","oferta":"Todos os 100 bilhões de XRP foram criados de uma vez, no lançamento da rede. Não há mineração. A Ripple recebeu uma grande parte e mantém um volume em contas com liberação programada (escrow). Uma fração mínima de XRP é destruída como taxa em cada transação, então a quantidade total diminui muito devagar.","fatos":[["Lançamento","2012"],["Criadores","David Schwartz, Jed McCaleb e Arthur Britto"],["Como a rede se mantém","Protocolo de consenso entre validadores, sem mineração"],["Oferta máxima","100 bilhões de XRP, todos criados no início"],["Empresa ligada","Ripple"],["Confirmação","Poucos segundos"]],"riscos":"Grande parte da oferta está com a Ripple, e as liberações do escrow podem pesar no preço. O XRP passou anos no centro de um processo da SEC, a CVM americana, aberto em 2020, o que mostra como decisões regulatórias mexem com a moeda. O preço oscila muito."}' WHERE slug = 'xrp';
UPDATE coins SET about = '{"uso":"O BNB é a moeda da BNB Chain, rede de contratos inteligentes ligada à Binance, a maior corretora de cripto do mundo. Ele paga as taxas dessa rede, dá desconto em taxas de negociação na Binance e é usado em aplicativos de finanças descentralizadas e em lançamentos de novos projetos dentro do ecossistema.","oferta":"O BNB foi lançado em 2017 com 200 milhões de unidades. Desde então, parte é destruída periodicamente em queimas programadas, com a meta anunciada de reduzir a oferta total para 100 milhões. Uma parte das taxas pagas na rede também é queimada.","fatos":[["Lançamento","2017"],["Criador","Binance"],["Como a rede se mantém","Validadores (prova de participação com validadores escolhidos)"],["Oferta inicial","200 milhões de BNB"],["Meta de oferta","100 milhões, por queimas periódicas"],["Rede","BNB Chain"]],"riscos":"O BNB depende muito da saúde e da reputação da Binance. Em 2023, a corretora fez um acordo com o Departamento de Justiça americano e pagou bilhões de dólares por falhas no controle de lavagem de dinheiro. Problemas regulatórios ou operacionais da empresa afetam a moeda diretamente."}' WHERE slug = 'bnb';
UPDATE coins SET about = '{"uso":"A Solana é uma rede de contratos inteligentes feita para ser rápida e barata, com transações que custam frações de centavo. Ela ficou popular em memecoins, pagamentos com stablecoins, aplicativos de consumo e negociação descentralizada. O SOL paga as taxas da rede e é travado pelos validadores como garantia.","oferta":"O SOL não tem limite fixo de oferta. Há uma emissão anual para recompensar os validadores, que começou em 8% e cai 15% a cada ano até chegar a 1,5% ao ano. Metade de cada taxa básica paga na rede é queimada.","fatos":[["Lançamento","Março de 2020"],["Criador","Anatoly Yakovenko (Solana Labs)"],["Como a rede se mantém","Prova de participação com prova de histórico"],["Oferta máxima","Sem limite; emissão anual decrescente até 1,5%"],["Taxa média","Frações de centavo"],["Usos fortes","Memecoins, pagamentos e negociação"]],"riscos":"A rede já ficou fora do ar várias vezes em 2021 e 2022, embora tenha ficado mais estável depois. A moeda sofreu muito com a quebra da FTX em 2022, que era grande apoiadora do projeto. O mercado de memecoins da rede tem muitos golpes e projetos abandonados."}' WHERE slug = 'solana';
UPDATE coins SET about = '{"uso":"O USD Coin (USDC) é uma stablecoin que busca valer sempre US$ 1. É usado para guardar dólares digitais, fazer pagamentos e transferências internacionais e como moeda base em aplicativos de finanças descentralizadas. É muito usado por empresas por causa dos relatórios frequentes sobre as reservas.","oferta":"Não há limite de oferta: a Circle, empresa americana que emite o USDC, cria moedas quando recebe dólares e destrói quando devolve. As reservas ficam em dinheiro e em títulos de curto prazo do governo americano, com relatórios mensais de uma firma de auditoria.","fatos":[["Lançamento","2018"],["Emissor","Circle"],["Atrelada a","Dólar americano (US$ 1)"],["Oferta máxima","Sem limite; acompanha as reservas"],["Reservas","Dinheiro e títulos de curto prazo dos EUA"],["Pode bloquear endereços?","Sim, o emissor pode congelar USDC"]],"riscos":"Em março de 2023, o USDC chegou a valer cerca de US$ 0,88 por algumas horas, quando a Circle informou ter parte das reservas presa no Silicon Valley Bank, que quebrou. O valor voltou a US$ 1, mas o episódio mostra que o lastro depende de bancos e de um emissor privado. Em reais, o valor acompanha o dólar.","guia":{"href":"/guias/stablecoins-o-que-sao-e-para-que-servem","titulo":"Stablecoins: o que são e para que servem"}}' WHERE slug = 'usdc';
UPDATE coins SET about = '{"uso":"O dogecoin nasceu como brincadeira com o meme do cachorro shiba inu e virou uma das maiores criptomoedas do mundo. É usado para gorjetas, pequenos pagamentos e, principalmente, como ativo especulativo muito influenciado pelas redes sociais e por personalidades como Elon Musk.","oferta":"O dogecoin não tem limite de oferta. São criados 10 mil DOGE a cada bloco, com um bloco por minuto, o que soma cerca de 5 bilhões de moedas novas por ano. Como esse número é fixo, a inflação em porcentagem cai devagar à medida que o total cresce.","fatos":[["Lançamento","Dezembro de 2013"],["Criadores","Billy Markus e Jackson Palmer"],["Como a rede se mantém","Mineração (prova de trabalho, junto com o Litecoin)"],["Oferta máxima","Sem limite; cerca de 5 bilhões novos por ano"],["Tempo médio de bloco","1 minuto"],["Origem do nome","Meme \\"Doge\\""]],"riscos":"O preço do dogecoin depende muito de humor das redes sociais e de declarações de famosos, e pode subir ou cair dezenas de pontos percentuais em dias. A emissão sem limite pressiona o valor ao longo do tempo. Golpes com sorteios falsos de DOGE em nome de celebridades são comuns.","guia":{"href":"/guias/golpes-com-cripto-como-reconhecer-e-se-proteger","titulo":"Golpes com cripto: como reconhecer e se proteger"}}' WHERE slug = 'dogecoin';
UPDATE coins SET about = '{"uso":"A Cardano é uma rede de contratos inteligentes que se apresenta como desenvolvida com base em pesquisa acadêmica revisada por pares. Ela é usada para aplicativos de finanças descentralizadas, emissão de tokens e projetos de identidade digital. O ADA paga as taxas e é usado para participar da validação e das votações da rede.","oferta":"O ADA tem limite de 45 bilhões de unidades. Uma parte foi vendida no lançamento e o restante é liberado aos poucos como recompensa para quem participa da validação (staking), em ritmo decrescente. Na Cardano, quem delega ADA a um validador não precisa travar a moeda.","fatos":[["Lançamento","Setembro de 2017"],["Criador","Charles Hoskinson (cofundador do ethereum)"],["Como a rede se mantém","Prova de participação (protocolo Ouroboros)"],["Oferta máxima","45 bilhões de ADA"],["Contratos inteligentes","Desde setembro de 2021"],["Desenvolvimento","Input Output (IOG), Cardano Foundation e Emurgo"]],"riscos":"A Cardano tem menos aplicativos e menos dinheiro circulando em DeFi do que redes concorrentes, e o desenvolvimento por etapas costuma ser mais lento. Como toda criptomoeda, o ADA oscila muito e já perdeu grande parte do valor em ciclos de baixa."}' WHERE slug = 'cardano';
UPDATE coins SET about = '{"uso":"A TRON é uma rede de contratos inteligentes muito usada para transferir stablecoins, principalmente USDT, por causa das taxas baixas e da rapidez. Boa parte dos tethers do mundo circula nela. O TRX paga os recursos da rede e é usado para votar nos validadores.","oferta":"O TRX não tem limite fixo de oferta. Há emissão de moedas novas para os validadores, mas parte das taxas pagas na rede é queimada, e em vários períodos a quantidade total diminuiu.","fatos":[["Lançamento","2017 (rede própria em 2018)"],["Criador","Justin Sun"],["Como a rede se mantém","27 \\"super representantes\\" eleitos (prova de participação delegada)"],["Oferta máxima","Sem limite fixo; parte das taxas é queimada"],["Uso principal","Transferências de USDT"],["Taxas","Baixas, pagas em TRX ou com recursos travados"]],"riscos":"A rede é bem mais concentrada que outras: poucos validadores e grande influência do fundador. Justin Sun foi alvo de processo da SEC em 2023. A TRON também aparece com frequência em investigações de golpes e lavagem de dinheiro com USDT, o que pode trazer medidas de autoridades."}' WHERE slug = 'tron';
UPDATE coins SET about = '{"uso":"A Chainlink é uma rede de oráculos: serviços que levam dados do mundo real, como cotações de moedas, para dentro das blockchains, onde os contratos inteligentes não conseguem buscar informação sozinhos. Muitos aplicativos de finanças descentralizadas dependem desses preços. A rede também oferece um protocolo para mover dados e tokens entre blockchains diferentes. O LINK paga os operadores da rede.","oferta":"O LINK foi criado com 1 bilhão de unidades, sem emissão nova. Parte foi vendida em 2017, parte ficou com os operadores e incentivos da rede e parte com a empresa que desenvolve o projeto. Os operadores podem travar LINK (staking) como garantia do serviço.","fatos":[["Lançamento","2017"],["Criadores","Sergey Nazarov e Steve Ellis"],["Tipo","Token na rede ethereum (padrão ERC-20)"],["Oferta máxima","1 bilhão de LINK"],["Uso principal","Cotações e dados para contratos inteligentes"],["Empresa ligada","Chainlink Labs"]],"riscos":"O valor do LINK depende de a rede continuar sendo usada e de o token continuar necessário para pagar os serviços. Uma parte grande da oferta está com a empresa e com reservas do projeto, que podem ser vendidas. O preço oscila muito.","guia":{"href":"/guias/defi-sem-susto-rendimentos-e-riscos","titulo":"DeFi sem susto: de onde vêm os rendimentos e quais são os riscos"}}' WHERE slug = 'chainlink';
UPDATE coins SET about = '{"uso":"A Stellar é uma rede de pagamentos voltada para remessas internacionais, transferências baratas e emissão de moedas digitais, inclusive stablecoins como o USDC. Bancos, empresas de remessa e programas de ajuda humanitária já usaram a rede. O XLM paga as taxas, que são mínimas, e serve como ponte entre moedas.","oferta":"Não há mineração. Foram criados 100 bilhões de XLM no início; em 2019, a fundação que cuida da rede queimou cerca de metade, e a oferta total ficou em torno de 50 bilhões. No mesmo ano acabou a emissão anual de moedas novas.","fatos":[["Lançamento","2014"],["Criadores","Jed McCaleb e Joyce Kim"],["Como a rede se mantém","Stellar Consensus Protocol, sem mineração"],["Oferta total","Cerca de 50 bilhões de XLM, sem emissão nova"],["Organização","Stellar Development Foundation"],["Confirmação","Poucos segundos"]],"riscos":"A Stellar disputa o mercado de pagamentos com redes maiores e com o próprio XRP, que tem proposta parecida. A fundação ainda guarda uma parte relevante dos XLM. Como toda criptomoeda, o preço oscila muito."}' WHERE slug = 'stellar';
UPDATE coins SET about = '{"uso":"O Toncoin (TON) é a moeda da The Open Network, rede que nasceu de um projeto do Telegram e hoje está integrada ao aplicativo de mensagens, com carteira embutida e minijogos e aplicativos dentro dos chats. O TON paga as taxas da rede, transferências entre usuários e serviços dentro do Telegram.","oferta":"A rede começou com cerca de 5 bilhões de TON. Há uma pequena emissão anual para recompensar os validadores, e parte das taxas é queimada.","fatos":[["Origem","Projeto do Telegram (2018), abandonado pela empresa em 2020"],["Mantida por","Comunidade e TON Foundation"],["Como a rede se mantém","Prova de participação"],["Oferta inicial","Cerca de 5 bilhões de TON"],["Integração","Carteira e minijogos no Telegram"],["Taxas","Baixas"]],"riscos":"O Telegram teve de abandonar o projeto original depois de um processo da SEC em 2020, e a rede segue muito dependente da integração com o aplicativo. Uma parte grande da oferta está concentrada em poucas carteiras. Minijogos e \\"airdrops\\" no Telegram são terreno comum para golpes.","guia":{"href":"/guias/golpes-com-cripto-como-reconhecer-e-se-proteger","titulo":"Golpes com cripto: como reconhecer e se proteger"}}' WHERE slug = 'toncoin';
UPDATE coins SET about = '{"uso":"O Shiba Inu (SHIB) é uma memecoin criada como \\"concorrente\\" do dogecoin. Começou como piada, mas formou uma comunidade grande e ganhou uma corretora descentralizada própria e uma rede de camada 2 chamada Shibarium. Na prática, a maior parte das pessoas compra SHIB como aposta especulativa.","oferta":"Foram criados 1 quatrilhão de SHIB (1.000.000.000.000.000). Metade foi enviada ao criador do ethereum, Vitalik Buterin, que em 2021 queimou a maior parte e doou o resto. A comunidade faz queimas voluntárias, mas a quantidade continua enorme, por isso o preço de uma unidade tem muitas casas decimais.","fatos":[["Lançamento","Agosto de 2020"],["Criador","Anônimo, conhecido como \\"Ryoshi\\""],["Tipo","Token na rede ethereum (padrão ERC-20)"],["Oferta inicial","1 quatrilhão de SHIB"],["Rede própria","Shibarium (camada 2, desde 2023)"],["Categoria","Memecoin"]],"riscos":"O valor de uma memecoin depende quase só do interesse do público e pode despencar sem aviso. O preço baixo por unidade dá a falsa impressão de que a moeda está \\"barata\\" ou de que pode chegar a R$ 1, o que exigiria um valor de mercado irreal. Golpes com tokens parecidos são comuns.","guia":{"href":"/guias/golpes-com-cripto-como-reconhecer-e-se-proteger","titulo":"Golpes com cripto: como reconhecer e se proteger"}}' WHERE slug = 'shiba-inu';
UPDATE coins SET about = '{"uso":"A Polkadot é uma rede que conecta várias blockchains, chamadas parachains, que compartilham a mesma segurança e conseguem trocar informações entre si. O DOT é usado para participar da validação, votar nas decisões da rede e reservar espaço para novas blockchains conectadas.","oferta":"O DOT não nasceu com limite fixo: há emissão anual de moedas novas para os validadores e para o tesouro da rede. Em 2020, a unidade foi redenominada (cada DOT antigo virou 100). As regras de emissão são decididas por votação dos detentores de DOT, que podem mudá-las.","fatos":[["Lançamento","2020"],["Criador","Gavin Wood (cofundador do ethereum)"],["Como a rede se mantém","Prova de participação nomeada (NPoS)"],["Oferta","Definida pela governança da rede"],["Organização","Web3 Foundation e Parity Technologies"],["Diferencial","Várias blockchains conectadas (parachains)"]],"riscos":"A proposta técnica é complexa e disputa espaço com outras redes de contratos inteligentes e soluções de interoperabilidade. A emissão definida por votação pode mudar. O DOT perdeu grande parte do valor desde o pico de 2021, e o preço segue muito volátil."}' WHERE slug = 'polkadot';
UPDATE coins SET about = '{"uso":"O Litecoin foi criado em 2011 como uma versão mais leve e rápida do bitcoin, para pagamentos do dia a dia. Por ser uma das criptomoedas mais antigas, é aceito em muitas corretoras e meios de pagamento, e costuma ser usado para transferências com taxas baixas.","oferta":"O Litecoin tem limite de 84 milhões de moedas, quatro vezes o do bitcoin. Assim como no bitcoin, a recompensa dos mineradores cai pela metade a cada 840 mil blocos, mais ou menos a cada quatro anos. O último halving foi em agosto de 2023.","fatos":[["Lançamento","Outubro de 2011"],["Criador","Charlie Lee"],["Como a rede se mantém","Mineração (prova de trabalho, algoritmo Scrypt)"],["Oferta máxima","84 milhões de LTC"],["Tempo médio de bloco","2,5 minutos"],["Halving","A cada 840 mil blocos"]],"riscos":"O Litecoin perdeu espaço para stablecoins e redes mais novas como meio de pagamento, e tem pouco uso fora das transferências. Como toda criptomoeda, oscila muito, e seu preço tende a seguir o movimento do bitcoin.","guia":{"href":"/guias/halving-do-bitcoin-o-que-e-e-quando-acontece","titulo":"Halving do bitcoin: o que é e quando acontece"}}' WHERE slug = 'litecoin';
UPDATE coins SET about = '{"uso":"O Bitcoin Cash surgiu em 2017 de uma divisão (fork) do bitcoin, defendida por quem queria blocos maiores para que a rede servisse como dinheiro do dia a dia, com taxas baixas. Quem tinha bitcoin na data da divisão recebeu a mesma quantidade de Bitcoin Cash.","oferta":"Segue as regras herdadas do bitcoin: limite de 21 milhões de moedas e recompensa dos mineradores cortada pela metade a cada 210 mil blocos. O último halving foi em abril de 2024, poucos dias antes do bitcoin.","fatos":[["Lançamento","1º de agosto de 2017 (fork do bitcoin)"],["Origem","Divisão da comunidade do bitcoin"],["Como a rede se mantém","Mineração (prova de trabalho)"],["Oferta máxima","21 milhões de BCH"],["Tamanho do bloco","Bem maior que o do bitcoin"],["Halving","A cada 210 mil blocos"]],"riscos":"O Bitcoin Cash é minerado com as mesmas máquinas do bitcoin, mas tem bem menos poder de mineração, o que o deixa mais exposto a ataques. Tem pouco uso como pagamento e já passou por outras divisões na própria comunidade. O preço é muito volátil.","guia":{"href":"/guias/o-que-e-bitcoin-de-verdade","titulo":"O que é bitcoin, de verdade"}}' WHERE slug = 'bitcoin-cash';
UPDATE coins SET about = '{"uso":"A Sui é uma rede de contratos inteligentes feita para processar muitas transações ao mesmo tempo, com taxas baixas, mirando jogos, aplicativos de consumo e finanças descentralizadas. Os programas são escritos na linguagem Move. O SUI paga as taxas, é travado pelos validadores e usado nas votações.","oferta":"O SUI tem limite de 10 bilhões de unidades. Uma parte entrou em circulação no lançamento e o restante é liberado aos poucos, em datas programadas, para investidores, a equipe, a fundação e programas de incentivo.","fatos":[["Lançamento","Maio de 2023"],["Criadores","Mysten Labs (ex-engenheiros do projeto de moeda da Meta)"],["Como a rede se mantém","Prova de participação delegada"],["Oferta máxima","10 bilhões de SUI"],["Linguagem","Move"],["Organização","Sui Foundation"]],"riscos":"É uma rede jovem, com histórico curto. As liberações programadas de SUI para investidores e equipe colocam moedas novas no mercado e podem pesar no preço. A rede já teve uma interrupção de algumas horas em 2024. O preço oscila muito."}' WHERE slug = 'sui';
UPDATE coins SET about = '{"uso":"A Uniswap é a maior corretora descentralizada do ethereum: um conjunto de contratos inteligentes onde qualquer pessoa troca um token por outro direto da própria carteira, sem cadastro. O UNI é o token de governança: quem tem UNI vota nas mudanças do protocolo e no uso do tesouro.","oferta":"O UNI foi lançado em 2020 com 1 bilhão de unidades, distribuídas a usuários (cada carteira que já tinha usado a Uniswap recebeu 400 UNI), à comunidade, à equipe e aos investidores. As regras permitem uma emissão de até 2% ao ano a partir de 2024, se a governança decidir.","fatos":[["Protocolo no ar","Novembro de 2018"],["Token UNI","Setembro de 2020"],["Criador","Hayden Adams"],["Tipo","Token de governança (ERC-20)"],["Oferta inicial","1 bilhão de UNI"],["Empresa ligada","Uniswap Labs"]],"riscos":"Usar corretoras descentralizadas exige cuidado: é fácil trocar por um token falso com nome parecido, e os sites de cópia são comuns. O UNI depende de decisões da governança e da regulação de corretoras descentralizadas. O preço oscila muito.","guia":{"href":"/guias/defi-sem-susto-rendimentos-e-riscos","titulo":"DeFi sem susto: de onde vêm os rendimentos e quais são os riscos"}}' WHERE slug = 'uniswap';
UPDATE coins SET about = '{"uso":"A Avalanche é uma plataforma de contratos inteligentes conhecida pela confirmação rápida das transações e por permitir que empresas e projetos criem redes próprias, ligadas à rede principal. É usada em finanças descentralizadas, jogos e testes de tokenização por instituições financeiras. O AVAX paga as taxas e é travado pelos validadores.","oferta":"O AVAX tem limite de 720 milhões de unidades. Uma parte foi distribuída no lançamento e o resto é emitido aos poucos como recompensa para os validadores. Todas as taxas pagas na rede são queimadas.","fatos":[["Lançamento","Setembro de 2020"],["Criador","Emin Gün Sirer (Ava Labs)"],["Como a rede se mantém","Prova de participação"],["Oferta máxima","720 milhões de AVAX"],["Taxas","Queimadas"],["Diferencial","Redes próprias ligadas à principal"]],"riscos":"A Avalanche disputa espaço com ethereum, Solana e outras redes, e o uso de aplicativos nela caiu em relação ao pico de 2021. Como toda criptomoeda, o AVAX oscila muito e já perdeu grande parte do valor em ciclos de baixa."}' WHERE slug = 'avalanche';
